def iso(ts: float | None) -> str:
    if not ts:
        return ''
    return datetime.fromtimestamp(ts, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')

def clip(text: str, n: int=240) -> str:
    t = ' '.join((text or '').split())
    return t if len(t) <= n else t[:n - 1] + '…'

