SUFFIX = re.compile('-(?:fix\\d*|next\\d*|cx|impl|followup|review|unified)$')
URL = re.compile('https://github\\.com/(?:[\\w.-]+/)([\\w.-]+)/(issues|pull)/(\\d+)')
KEYWORD = re.compile('(?i)\\b(PRs?|pull request|issues?|closes|fixes|resolves|addresses|refs?)\\s+(?:([\\w.-]+(?:/[\\w.-]+)?)\\s*)?#(\\d+)')

def root_task(slug: str) -> str:
    previous = None
    while previous != slug:
        previous, slug = (slug, SUFFIX.sub('', slug))
    return slug

def repo_of(it: dict, notes: dict, tasks: dict) -> str:
    repo = notes.get('repo') or it['repo']
    if repo and repo != 'orchestra':
        return short_repo(repo)
    for slug in it['slugs']:
        text = tasks.get(slug, {}).get('text', '')
        m = re.search('/data/dev/(?:projects|services|libs)/([\\w.-]+)', text)
        if m:
            return short_repo(m[1].rstrip('.'))
        mentioned = {r for r, _ in refs(text)} | {short_repo(m[1]) for m in URL.finditer(text)}
        if len(mentioned) == 1:
            return next(iter(mentioned))
        for name in sorted(set(FULL) | set(FULL.values()), key=len, reverse=True):
            if slug.startswith((name + '-', 'issue-' + name + '-', 'review-' + name + '-')):
                return short_repo(name)
    return short_repo(repo or '')

def explicit_refs(text: str, repo: str) -> dict[str, set[int]]:
    found = {'issue': set(), 'pr': set()}
    for m in KEYWORD.finditer(text or ''):
        if text[:m.start()].rstrip().lower().endswith('forgejo'):
            continue
        if m[2] and (short_repo(m[2]) == repo or repo.endswith('-' + m[2])) or (not m[2] and repo not in ('', 'orchestra')):
            found['pr' if m[1].lower() in ('pr', 'prs', 'pull request') else 'issue'].add(int(m[3]))
    for m in URL.finditer(text or ''):
        if short_repo(m[1]) == repo:
            found['issue' if m[2] == 'issues' else 'pr'].add(int(m[3]))
    return found

def identity(it: dict, notes: dict, tasks: dict, pr_issues: dict, known_prs: set | None=None) -> tuple[str, int | None, int | None]:
    repo = repo_of(it, notes, tasks)
    issue = (it.get('issue') or {}).get('number')
    pr = (it.get('pr') or {}).get('number')
    issue = issue or (notes.get('issue') if type(notes.get('issue')) is int else None)
    pr = pr or (notes.get('pr') if type(notes.get('pr')) is int else None)
    for slug in it['slugs'] or [it['id']]:
        m = re.match('^(issue|pr|review)-(.+)-(\\d+)(?:[a-z]|-(?:fix|next)\\d*)?$', slug)
        if m and (short_repo(m[2]) == repo or repo.endswith('-' + m[2])):
            if m[1] == 'issue':
                issue = issue or int(m[3])
            else:
                pr = pr or int(m[3])
        m = re.match('^review-(?:claude-|codex-)?(\\d+)[a-z]?$', slug)
        if m and repo not in ('', 'orchestra'):
            pr = pr or int(m[1])
        m = re.match('^(.+)-(\\d+)-(?:fix\\d*|sync\\d*)$', slug)
        if m and (short_repo(m[1]) == repo or repo.endswith('-' + m[1])):
            pr = pr or int(m[2])
    headers = '\n'.join((tasks.get(s, {}).get('header', '') for s in it['slugs']))
    found = explicit_refs(headers, repo)
    outcomes = explicit_refs('\n'.join((str(o.get(k) or '') for o in it.get('outcomes', []) for k in ('gates', 'note'))), repo)
    finals = explicit_refs('\n'.join((c.get('report', '') for c in it['children'])), repo)
    body = explicit_refs('\n'.join((tasks.get(s, {}).get('text', '') for s in it['slugs'])), repo)
    primary_prs = found['pr'] or outcomes['pr'] or body['pr'] or finals['pr']
    if not pr and len(primary_prs) == 1:
        pr = next(iter(primary_prs))
    issue = issue or pr_issues.get((repo, pr))
    primary_issues = found['issue'] or outcomes['issue'] or body['issue'] or finals['issue']
    known_unlinked_pr = bool(pr and (repo, pr) in known_prs and (not pr_issues.get((repo, pr))))
    if not issue and len(primary_issues) == 1 and (not known_unlinked_pr):
        issue = next(iter(primary_issues))
    if issue and (repo, issue) in (set(pr_issues) if known_prs is None else known_prs):
        pr, issue = (pr or issue, None)
    return (repo, issue, pr)

def groups(items: dict, notes: dict, tasks: dict, pr_issues: dict) -> tuple[dict, dict]:
    known_prs = set(pr_issues)
    identities = {iid: identity(it, notes.get(iid, {}), tasks, pr_issues, known_prs) for iid, it in items.items()}
    declared: dict[tuple, set[int]] = {}
    for repo, issue, pr in identities.values():
        if issue and pr:
            declared.setdefault((repo, pr), set()).add(issue)
    pr_issues = {**pr_issues, **{ref: next(iter(issues)) for ref, issues in declared.items() if len(issues) == 1 and (not pr_issues.get(ref))}}
    identities = {iid: identity(it, notes.get(iid, {}), tasks, pr_issues, known_prs) for iid, it in items.items()}
    roots: dict[str, set[str]] = {}
    for iid, it in items.items():
        for slug in it['slugs'] or [iid]:
            if identities[iid][0] not in ('', 'orchestra'):
                roots.setdefault(root_task(slug), set()).add(identities[iid][0])
    for iid, it in items.items():
        if identities[iid][0] in ('', 'orchestra'):
            repos = set().union(*(roots.get(root_task(s), set()) for s in it['slugs'] or [iid]))
            if len(repos) == 1:
                repo = next(iter(repos))
                identities[iid] = identity({**it, 'repo': repo}, notes.get(iid, {}), tasks, pr_issues, known_prs)
    families: dict[tuple[str, str], list[str]] = {}
    for iid, it in items.items():
        repo = identities[iid][0]
        for slug in it['slugs'] or [iid]:
            families.setdefault((repo, root_task(slug)), []).append(iid)
    proposals: dict[str, set[int]] = {}
    for members in families.values():
        issues = {identities[i][1] for i in members} - {None}
        if len(issues) == 1:
            for iid in members:
                if not identities[iid][1]:
                    proposals.setdefault(iid, set()).update(issues)
    for iid, issues in proposals.items():
        if len(issues) == 1:
            repo, _, pr = identities[iid]
            identities[iid] = (repo, next(iter(issues)), pr)
    for (_, root), members in families.items():
        if any((identities[i][1] or len(proposals.get(i, set())) > 1 for i in members)):
            continue
        anchored = [i for i in members if identities[i][2]]
        if anchored:

            def root_rank(iid: str) -> tuple:
                slugs = [s for s in items[iid]['slugs'] if root_task(s) == root] or [iid]
                return min(((len(s), s) for s in slugs))
            anchor = identities[min(anchored, key=root_rank)]
            for iid in members:
                identities[iid] = anchor
    result: dict[str, list[str]] = {}
    for iid, it in items.items():
        repo, issue, pr = identities[iid]
        if issue:
            target = f'issue-{repo}-{issue}'
        elif pr:
            target = f'pr-{repo}-{pr}'
        else:
            slugs = it['slugs'] or [iid]
            family = families.get((repo, root_task(slugs[0])), [iid])
            unanchored = [s for s in family if not identities[s][1] and (not identities[s][2])]
            target = min(unanchored or [iid], key=lambda s: (len(s), s))
        result.setdefault(target, []).append(iid)
    return (result, identities)

