class Assembly:

    def __init__(self, spawns: dict, led: dict, prs: list[dict], probes: Probes) -> None:
        self.items: dict[str, dict] = {}
        self.spawns, self.led, self.probes = (spawns, led, probes)
        self.pr_by = {(short_repo(p['repository']['name']), p['number']): p for p in prs}
        self.produced: dict[tuple[str, int], str] = {}

    def pr_issue(self, ref: tuple[str, int]) -> int | None:
        p = self.pr_by.get(ref)
        if not p or ref in _DETACHED:
            return None
        meta = self.probes.pr_meta(ref[0]).get(ref[1], {})
        for linked in p.get('closingIssuesReferences') or meta.get('closingIssuesReferences', []):
            number = linked.get('number') if isinstance(linked, dict) else None
            linked_repo = (linked.get('repository') or {}).get('name', '') if isinstance(linked, dict) else ''
            if type(number) is int and (not linked_repo or short_repo(linked_repo) == ref[0]) and ((ref[0], number) not in self.pr_by):
                return number
        m = re.findall('(?i)\\b(?:closes|fixes|resolves|addresses)\\s+#(\\d+)', p.get('body') or '')
        actual_issues = [int(n) for n in m if (ref[0], int(n)) not in self.pr_by]
        if actual_issues:
            return actual_issues[0]
        issues = {n for n in explicit_refs(p.get('body') or '', ref[0])['issue'] if (ref[0], n) not in self.pr_by}
        if len(issues) == 1:
            return next(iter(issues))
        branch = p.get('headRefName', '')
        m = re.match('auto/issue-(?:[\\w.-]+-)?(\\d+)(?:-.+)?$', branch)
        return int(m[1]) if m and (ref[0], int(m[1])) not in self.pr_by else None

