class Probes:

    def _once(self, key, fn):
        if key not in self._memo:
            self._memo[key] = fn()
        return self._memo[key]

    def pr_meta(self, short: str) -> dict[int, dict]:
        """Return state, refs, review and merge metadata by PR number for one repo."""
        return self._once(('meta', short), lambda: self._pr_meta(short))

    def is_ancestor(self, short: str, commit: str, ref: str, persist: bool=True) -> bool | None:
        """True/False, or None when a commit is unknown locally. Fixed shas are cached on disk."""
        if short not in REPO_GIT or not commit or (not ref):
            return None
        key = f'{short}:{commit}:{ref}'
        if persist and key in self._anc:
            return self._anc[key]

        def ask() -> bool | None:
            rc, _ = self.git(short, 'merge-base', '--is-ancestor', commit, ref)
            return True if rc == 0 else False if rc == 1 else None
        res = self._once(('anc', key), ask)
        if persist and res is not None:
            self._anc[key], self._anc_dirty = (res, True)
        return res

    def main_contains(self, short: str, commit: str) -> bool | None:
        if short not in REPO_GIT or not commit:
            return None
        key = f'{short}:{commit}:main'
        if self._anc.get(key):
            return True
        self.fetch(short)
        ref = self.main_ref(short)
        res = self.is_ancestor(short, commit, ref, persist=False) if ref else None
        if res:
            self._anc[key], self._anc_dirty = (True, True)
        return res

    def tag_contains(self, short: str, commit: str, pattern: str) -> bool | None:
        if short not in REPO_GIT or not commit:
            return None
        key = f'{short}:{commit}:tag:{pattern}'
        if self._anc.get(key):
            return True

        def ask() -> bool | None:
            self.fetch(short)
            rc, out = self.git(short, 'tag', '--contains', commit, '-l', pattern)
            return None if rc != 0 else bool(out.strip())
        res = self._once(('tag', key), ask)
        if res:
            self._anc[key], self._anc_dirty = (True, True)
        return res

    def atrium_version(self) -> str:

        def ask() -> str:
            rc, out = self._run(['docker', 'exec', 'atrium', 'printenv', 'ATRIUM_VERSION'], 10)
            v = out.strip()
            return v if rc == 0 and SHA_RE.fullmatch(v) else ''
        return self._once('atrium', ask)

    def deploy_shas(self, short: str) -> list[str] | None:
        """Shas with a green deploy job on Forgejo; None when unknown."""
        if short not in FORGEJO_REPO:
            return None

        def ask() -> list[str] | None:
            cache = self.cache / f'fj-{short}.json'
            rows = None
            if cache.exists() and time.time() - cache.stat().st_mtime < FJ_TTL:
                rows = read_json(cache, None)
            if rows is None:
                rc, out = self._run(['fj', 'ci', 'tasks', FORGEJO_REPO[short], '--json', '--limit', '100'], 60)
                rows = parse_fj_tasks(out) if rc == 0 else None
                if rows is not None and self.cache.exists():
                    write_json(cache, rows)
            return None if rows is None else green_deploys(rows)
        return self._once(('fj', short), ask)

